package com.google.javascript.jscomp.type;

import com.google.common.base.Preconditions;
import com.google.javascript.jscomp.CodingConvention;
import com.google.javascript.jscomp.Compiler;
import com.google.javascript.jscomp.Token;
import com.google.javascript.jscomp.ast.Node;
import com.google.javascript.jscomp.ast.NodeUtil;
import com.google.javascript.jscomp.type.JSType;
import com.google.javascript.jscomp.type.JSTypeRegistry;
import com.google.javascript.jscomp.webpack.ClosurePass;
import com.google.javascript.rhino.Node;
import com.google.javascript.rhino.Token;
import com.google.javascript.rhino.jstype.EnumElementType;
import com.google.javascript.rhino.jstype.FunctionType;
import com.google.javascript.rhino.jstype.JSType;
import com.google.javascript.rhino.jstype.JSTypeNative;
import com.google.javascript.rhino.jstype.JSTypeRegistry;
import com.google.javascript.rhino.jstype.ObjectType;
import com.google.javascript.rhino.jstype.ParameterizedType;
import com.google.javascript.rhino.jstype.StaticSlot;
import com.google.javascript.rhino.jstype.TemplateType;
import com.google.javascript.rhino.jstype.UnionType;
import com.google.javascript.rhino.jstype.Visitor;
import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static com.google.javascript.jscomp.Assert.assertEquals;
import static com.google.javascript.jscomp.Assert.assertNull;
import static org.junit.Assert.*;
import static org.junit.Assert.assertNotNull;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.when;

public class ChainableReverseAbstractInterpreter_getTypeIfRefinable_TriageGen0Test {

    private ChainableReverseAbstractInterpreter interpreter;
    private JSTypeRegistry typeRegistry;
    private CodingConvention convention;

    @Mock
    private Node mockNode;

    @Mock
    private FlowScope mockScope;

    @Mock
    private StaticSlot<JSType> mockSlot;

    @Before
    public void setUp() {
        MockitoAnnotations.openMocks(this);
        typeRegistry = new JSTypeRegistry();
        convention = new Compiler().getCodingConvention();
        interpreter = new ChainableReverseAbstractInterpreter(convention, typeRegistry);
    }

    /**
     * Test Case: Token.NAME, slot exists, slot type is not null.
     */
    @Test
    public void testGetTypeIfRefinable_Name_SlotExists_TypeNotNull() {
        JSType expectedType = typeRegistry.getNativeType(JSType.STRING);
        when(mockNode.getType()).thenReturn(Token.NAME);
        when(mockNode.getString()).thenReturn("varName");
        when(mockScope.getSlot("varName")).thenReturn(mockSlot);
        when(mockSlot.getType()).thenReturn(expectedType);

        JSType result = interpreter.getTypeIfRefinable(mockNode, mockScope);

        assertEquals(expectedType, result);
    }

    /**
     * Test Case: Token.NAME, slot exists, but slot type is null (fallback to node type).
     */
    @Test
    public void testGetTypeIfRefinable_Name_SlotExists_TypeNull_FallbackToNode() {
        JSType nodeType = typeRegistry.getNativeType(JSType.NUMBER);
        when(mockNode.getType()).thenReturn(Token.NAME);
        when(mockNode.getString()).thenReturn("varName");
        when(mockScope.getSlot("varName")).thenReturn(mockSlot);
        when(mockSlot.getType()).thenReturn(null);
        when(mockNode.getJSType()).thenReturn(nodeType);

        JSType result = interpreter.getTypeIfRefinable(mockNode, mockScope);

        assertEquals(nodeType, result);
    }

    /**
     * Test Case: Token.NAME, slot does not exist.
     */
    @Test
    public void testGetTypeIfRefinable_Name_SlotNotFound() {
        when(mockNode.getType()).thenReturn(Token.NAME);
        when(mockNode.getString()).thenReturn("unknownVar");
        when(mockScope.getSlot("unknownVar")).thenReturn(null);

        JSType result = interpreter.getTypeIfRefinable(mockNode, mockScope);

        assertNull(result);
    }

    /**
     * Test Case: Token.GETPROP, qualified name is null.
     */
    @Test
    public void testGetTypeIfRefinable_GetProp_QualifiedNameNull() {
        when(mockNode.getType()).thenReturn(Token.GETPROP);
        when(mockNode.getQualifiedName()).thenReturn(null);

        JSType result = interpreter.getTypeIfRefinable(mockNode, mockScope);

        assertNull(result);
    }

    /**
     * Test Case: Token.GETPROP, qualified name exists, slot exists, slot type is not null.
     */
    @Test
    public void testGetTypeIfRefinable_GetProp_SlotExists_TypeNotNull() {
        JSType expectedType = typeRegistry.getNativeType(JSType.BOOLEAN);
        when(mockNode.getType()).thenReturn(Token.GETPROP);
        when(mockNode.getQualifiedName()).thenReturn("obj.prop");
        when(mockScope.getSlot("obj.prop")).thenReturn(mockSlot);
        when(mockSlot.getType()).thenReturn(expectedType);

        JSType result = interpreter.getTypeIfRefinable(mockNode, mockScope);

        assertEquals(expectedType, result);
    }

    /**
     * Test Case: Token.GETPROP, qualified name exists, slot exists, but slot type is null (fallback to node type).
     */
    @Test
    public void testGetTypeIfRefinable_GetProp_SlotExists_TypeNull_FallbackToNode() {
        JSType nodeType = typeRegistry.getNativeType(JSType.STRING);
        when(mockNode.getType()).thenReturn(Token.GETPROP);
        when(mockNode.getQualifiedName()).thenReturn("obj.prop");
        when(mockScope.getSlot("obj.prop")).thenReturn(mockSlot);
        when(mockSlot.getType()).thenReturn(null);
        when(mockNode.getJSType()).thenReturn(nodeType);

        JSType result = interpreter.getTypeIfRefinable(mockNode, mockScope);

        assertEquals(nodeType, result);
    }

    /**
     * Test Case: Token.GETPROP, qualified name exists, slot exists, slot type is null, node type is null (fallback to UNKNOWN).
     */
    @Test
    public void testGetTypeIfRefinable_GetProp_SlotExists_TypeNull_NodeTypeNull_FallbackToUnknown() {
        when(mockNode.getType()).thenReturn(Token.GETPROP);
        when(mockNode.getQualifiedName()).thenReturn("obj.prop");
        when(mockScope.getSlot("obj.prop")).thenReturn(mockSlot);
        when(mockSlot.getType()).thenReturn(null);
        when(mockNode.getJSType()).thenReturn(null);

        JSType result = interpreter.getTypeIfRefinable(mockNode, mockScope);

        assertNotNull(result);
        // UNKNOWN_TYPE check
        assertEquals(typeRegistry.getNativeType(JSType.UNKNOWN), result);
    }

    /**
     * Test Case: Token.GETPROP, qualified name exists, slot does not exist, node type is not null.
     */
    @Test
    public void testGetTypeIfRefinable_GetProp_SlotNotFound_FallbackToNode() {
        JSType nodeType = typeRegistry.getNativeType(JSType.OBJECT);
        when(mockNode.getType()).thenReturn(Token.GETPROP);
        when(mockNode.getQualifiedName()).thenReturn("obj.prop");
        when(mockScope.getSlot("obj.prop")).thenReturn(null);
        when(mockNode.getJSType()).thenReturn(nodeType);

        JSType result = interpreter.getTypeIfRefinable(mockNode, mockScope);

        assertEquals(nodeType, result);
    }

    /**
     * Test Case: Token.GETPROP, qualified name exists, slot does not exist, node type is null (fallback to UNKNOWN).
     */
    @Test
    public void testGetTypeIfRefinable_GetProp_SlotNotFound_NodeTypeNull_FallbackToUnknown() {
        when(mockNode.getType()).thenReturn(Token.GETPROP);
        when(mockNode.getQualifiedName()).thenReturn("obj.prop");
        when(mockScope.getSlot("obj.prop")).thenReturn(null);
        when(mockNode.getJSType()).thenReturn(null);

        JSType result = interpreter.getTypeIfRefinable(mockNode, mockScope);

        assertNotNull(result);
        assertEquals(typeRegistry.getNativeType(JSType.UNKNOWN), result);
    }

    /**
     * Test Case: Node type is neither NAME nor GETPROP.
     */
    @Test
    public void testGetTypeIfRefinable_OtherTokenType() {
        when(mockNode.getType()).thenReturn(Token.ASSIGN);

        JSType result = interpreter.getTypeIfRefinable(mockNode, mockScope);

        assertNull(result);
    }
}
